import { expect, expectStatus, test } from "../../fixtures";

interface VendorPage {
  items: unknown[];
  total: number;
  limit: number;
  offset: number;
}

test.describe("vendor list paging", () => {
  test(
    "a page past the last vendor is empty but still reports the total",
    { tag: "@LIF-15" },
    async ({ apiAs }) => {
      // Arrange: a signed-in member, and the total from the first page.
      const member = await apiAs("member");
      const firstPage = await expectStatus<VendorPage>(
        await member.get("/api/vendors", { params: { limit: 20, offset: 0 } }),
        200,
      );

      // Act: request an offset far beyond any realistic total. Other tests create
      // vendors in parallel, so a fixed "total + 1" offset could fall inside the list.
      const pastEnd = await expectStatus<VendorPage>(
        await member.get("/api/vendors", { params: { limit: 20, offset: 1_000_000 } }),
        200,
      );

      // Assert
      expect(pastEnd.items).toEqual([]);
      expect(pastEnd.total).toBe(firstPage.total);
    },
  );
});
